async function choose(id,value,filter=false){
await W.ev("tab_y","document.getElementById("+JSON.stringify(id)+").closest('.select__control').scrollIntoView({block:'center',behavior:'instant'});true");
await tools.mcp__t3_code__preview_open({tabId:"tab_y",open:true});
let r=await tools.mcp__t3_code__preview_click({tabId:"tab_y",selector:'.select__control:has([id="'+id+'"]) button'});if(r.isError)throw Error(JSON.stringify(r));
await W.ev("tab_y","document.getElementById("+JSON.stringify(id)+").focus();true");
if(filter){r=await tools.mcp__t3_code__preview_type({tabId:"tab_y",selector:'input[id="'+id+'"]',text:value,clear:true});if(r.isError)throw Error(JSON.stringify(r));await W.delay(700)}
if(await W.ev("tab_y","document.getElementById("+JSON.stringify(id)+").getAttribute('aria-expanded')")!=="true"){await tools.mcp__t3_code__preview_click({tabId:"tab_y",selector:'.select__control:has([id="'+id+'"]) button'})}
const opts=await W.ev("tab_y","[...document.querySelectorAll('[role=option]')].filter(x=>x.id.startsWith('react-select')).map(x=>({text:x.innerText,id:x.id})).slice(0,120)");
const o=opts.find(x=>x.text.toLowerCase()===value.toLowerCase());if(!o){text({id,opts});return false}
await W.ev("tab_y","document.getElementById("+JSON.stringify(o.id)+").click();true");return true;
}
({choose});
